import { test, expect } from '@playwright/test';

test.describe('Notification Visual Distinction', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('http://localhost:3000/notifications');
    await page.waitForLoadState('networkidle');
  });

  test('should display unread notifications with distinct visual styling', async ({ page }) => {
    // Get all unread notification items
    const unreadNotifications = page.getByRole('listitem').filter({
      has: page.getByRole('status', { name: /unread/i })
    });

    // Verify unread notifications exist
    const unreadCount = await unreadNotifications.count();
    expect(unreadCount).toBeGreaterThan(0);

    // Check that unread notifications have distinct styling
    const firstUnreadNotification = unreadNotifications.first();

    // Verify unread notification has a visual indicator (e.g., bold text, different background)
    const unreadBadge = firstUnreadNotification.getByRole('status', { name: /unread/i });
    await expect(unreadBadge).toBeVisible();

    // Check for distinct styling attributes
    const computedStyle = await firstUnreadNotification.evaluate((element) => {
      const styles = window.getComputedStyle(element);
      return {
        backgroundColor: styles.backgroundColor,
        fontWeight: styles.fontWeight,
        borderLeft: styles.borderLeft,
        opacity: styles.opacity
      };
    });

    // Verify that unread notifications have some visual distinction
    expect(computedStyle.backgroundColor).not.toBe('rgba(0, 0, 0, 0)');
  });

  test('should display read notifications with different styling than unread', async ({ page }) => {
    // Get unread and read notifications
    const unreadNotifications = page.getByRole('listitem').filter({
      has: page.getByRole('status', { name: /unread/i })
    });

    const readNotifications = page.getByRole('listitem').filter({
      has: page.getByRole('status', { name: /read/i })
    });

    // Verify both types exist
    const unreadCount = await unreadNotifications.count();
    const readCount = await readNotifications.count();

    expect(unreadCount).toBeGreaterThan(0);
    expect(readCount).toBeGreaterThan(0);

    // Get styling of first unread notification
    const firstUnread = unreadNotifications.first();
    const unreadStyle = await firstUnread.evaluate((element) => {
      const styles = window.getComputedStyle(element);
      return {
        backgroundColor: styles.backgroundColor,
        fontWeight: styles.fontWeight,
        color: styles.color,
        opacity: styles.opacity
      };
    });

    // Get styling of first read notification
    const firstRead = readNotifications.first();
    const readStyle = await firstRead.evaluate((element) => {
      const styles = window.getComputedStyle(element);
      return {
        backgroundColor: styles.backgroundColor,
        fontWeight: styles.fontWeight,
        color: styles.color,
        opacity: styles.opacity
      };
    });

    // Verify that styling is different between read and unread
    const stylesDiffer = 
      unreadStyle.backgroundColor !== readStyle.backgroundColor ||
      unreadStyle.fontWeight !== readStyle.fontWeight ||
      unreadStyle.color !== readStyle.color ||
      unreadStyle.opacity !== readStyle.opacity;

    expect(stylesDiffer).toBeTruthy();
  });

  test('should maintain visual distinction when marking notification as read', async ({ page }) => {
    // Find an unread notification
    const unreadNotification = page.getByRole('listitem').filter({
      has: page.getByRole('status', { name: /unread/i })
    }).first();

    // Get initial styling
    const initialStyle = await unreadNotification.evaluate((element) => {
      const styles = window.getComputedStyle(element);
      return {
        backgroundColor: styles.backgroundColor,
        fontWeight: styles.fontWeight
      };
    });

    // Click mark as read button
    const markAsReadButton = unreadNotification.getByRole('button', { name: /mark as read|read/i });
    await markAsReadButton.click();

    // Wait for the notification to update
    await page.waitForTimeout(500);

    // Get new styling after marking as read
    const updatedStyle = await unreadNotification.evaluate((element) => {
      const styles = window.getComputedStyle(element);
      return {
        backgroundColor: styles.backgroundColor,
        fontWeight: styles.fontWeight
      };
    });

    // Verify that styling has changed
    const styleChanged = 
      initialStyle.backgroundColor !== updatedStyle.backgroundColor ||
      initialStyle.fontWeight !== updatedStyle.fontWeight;

    expect(styleChanged).toBeTruthy();
  });

  test('should show unread indicator badge on unread notifications', async ({ page }) => {
    // Find unread notifications
    const unreadNotifications = page.getByRole('listitem').filter({
      has: page.getByRole('status', { name: /unread/i })
    });

    const unreadCount = await unreadNotifications.count();
    expect(unreadCount).toBeGreaterThan(0);

    // Check that each unread notification has a visible indicator
    for (let i = 0; i < Math.min(unreadCount, 3); i++) {
      const notification = unreadNotifications.nth(i);
      const indicator = notification.locator('[data-testid="unread-indicator"], .unread-badge, .unread-dot');

      // Try to find visual indicator
      const indicatorVisible = await indicator.isVisible().catch(() => false);

      if (indicatorVisible) {
        await expect(indicator).toBeVisible();
      } else {
        // Alternative: check for status role
        const statusBadge = notification.getByRole('status');
        await expect(statusBadge).toBeVisible();
      }
    }
  });
});
